function validate([points]) {
  if (!Array.isArray(points) || points.length < 1 || points.length > 100) return 'points needs 1 to 100 points.';
  for (const point of points) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Coordinates are integers from -1000 to 1000.';
  }
  return null;
}

