function minTimeToVisitAllPoints(points) {
  // Walk the path one second at a time, stepping toward the next point on each axis that still differs.
  let [x, y] = points[0];
  let seconds = 0;
  for (const [tx, ty] of points) {
    while (x !== tx || y !== ty) {
      if (x < tx) x++; else if (x > tx) x--;
      if (y < ty) y++; else if (y > ty) y--;
      seconds++;
    }
  }
  return seconds;
}

