function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 1 + Math.floor(rand() * 6);
  // Small inputs sometimes use the full coordinate range so edge values are covered.
  const reach = large || rand() < 0.2 ? 1000 : 4;
  const coord = () => Math.floor(rand() * (2 * reach + 1)) - reach;
  const points = [];
  for (let i = 0; i < n; i++) {
    if (i > 0 && rand() < 0.15) points.push([...points[i - 1]]);
    else points.push([coord(), coord()]);
  }
  return [points];
}
